import subprocess,os,json,time
from pathlib import Path
R=Path('<RETREE_ROOT>')
N=Path('<NEO_ROOT>')
D=Path('/tmp/pr100-remeasure')
results=[]
def run(name,cmd,cwd,mode=None):
 env=os.environ.copy()
 if mode is not None: env['RETREE_COMPILER']=str(mode)
 start=time.time(); print('START',name,flush=True)
 with (D/(name+'.log')).open('w') as out: p=subprocess.run(cmd,cwd=cwd,env=env,stdout=out,stderr=subprocess.STDOUT)
 results.append(dict(name=name,seconds=time.time()-start,exit=p.returncode,cmd=cmd,cwd=str(cwd),mode=mode))
 (D/'runs.json').write_text(json.dumps(results,indent=2)); print('END',name,p.returncode,flush=True)
 if p.returncode: raise SystemExit(p.returncode)
for bench in ['node-reads','array-reads']:
 for i in range(3):
  for mode in ([0,1] if i%2==0 else [1,0]): run(f'{bench}-{mode}-{i+1}',['node','--expose-gc','scripts/run-sdk-scaling.mjs',f'benchmarks/{bench}.mts'],R,mode)
for i in range(3):
 for mode in ([0,1] if i%2==0 else [1,0]): run(f'frame-{mode}-{i+1}',['npx','tsx','scripts/benchmark-world-animation-frame-change.mts','--workspace','../../../neowyn/neo','--iterations','24'],N,mode)
heavy=(N/'scratch/ab-heavy.sh').read_text().split('--disableConsoleIntercept \\\n')[1].split('  > $out')[0].replace('\\','').split()
for i in range(3):
 for mode in ([0,1] if i%2==0 else [1,0]): run(f'heavy-{mode}-{i+1}',['npx','vitest','run','--project','heavy','--no-file-parallelism','--disableConsoleIntercept',*heavy],N,mode)
run('compile-time',['node','scratch/compile-time.mjs','/tmp/neo-ab/neo-files.txt','3'],N)
run('emit-size',['node','scratch/emit-size.mjs'],N)
