// Measures @babel/core transform time over a file list, with and without the
// Retree compiler, interleaved per round. Run from the Neo worktree.
import { readFileSync } from "node:fs";
import { transformSync } from "@babel/core";

const files = readFileSync(process.argv[2], "utf8").split("\n").filter(Boolean);
const rounds = Number(process.argv[3] ?? 3);
const bases = JSON.parse(readFileSync("/tmp/neo-bases.json", "utf8"));
const failures = new Set();
const sources = files.map((file) => ({ file, code: readFileSync(file, "utf8") }));

function configFor(compiler) {
    return {
        babelrc: false,
        configFile: false,
        presets: [["next/babel", { "preset-env": { modules: false, targets: { node: "current" } }, "preset-typescript": { allowDeclareFields: true } }]],
        plugins: [
            ...(compiler ? [["@retreejs/babel-plugin-compiler", { bases }]] : []),
            ["@babel/plugin-proposal-decorators", { version: "2023-11" }],
        ],
        sourceMaps: false,
        compact: false,
    };
}

function runLane(compiler) {
    const config = configFor(compiler);
    const perFile = [];
    const start = performance.now();
    for (const { file, code } of sources) {
        const t0 = performance.now();
        try { transformSync(code, { ...config, filename: file }); } catch (error) { failures.add(file + ": " + String(error).split("\n")[0]); }
        perFile.push([file, performance.now() - t0]);
    }
    return { total: performance.now() - start, perFile };
}

// warm both lanes once so JIT state is comparable
runLane(false); runLane(true);
const results = { proxy: [], compiled: [] };
for (let round = 0; round < rounds; round++) {
    const order = round % 2 === 0 ? [false, true] : [true, false];
    for (const compiler of order) {
        const lane = runLane(compiler);
        results[compiler ? "compiled" : "proxy"].push(lane);
        console.log(`round ${round + 1} ${compiler ? "compiled" : "proxy   "} ${lane.total.toFixed(0)} ms`);
    }
}
const median = (values) => { const s = [...values].sort((a, b) => a - b); return s[Math.floor(s.length / 2)]; };
const proxyTotal = median(results.proxy.map((r) => r.total));
const compiledTotal = median(results.compiled.map((r) => r.total));
console.log(`files ${files.length}, failures ${failures.size}`); for (const f of failures) console.log("  " + f);
console.log(`median total proxy ${proxyTotal.toFixed(0)} ms, compiled ${compiledTotal.toFixed(0)} ms, delta ${(compiledTotal - proxyTotal).toFixed(0)} ms (${((compiledTotal / proxyTotal - 1) * 100).toFixed(1)}%)`);
// per-file delta on the last rounds
const last = (lane) => results[lane][results[lane].length - 1].perFile;
const deltas = last("compiled").map(([file, ms], i) => [file, ms - last("proxy")[i][1], ms]);
deltas.sort((a, b) => b[1] - a[1]);
console.log("slowest deltas:");
for (const [file, delta, ms] of deltas.slice(0, 10)) console.log(`  +${delta.toFixed(2)} ms (${ms.toFixed(2)} ms) ${file}`);
const compiledFiles = deltas.filter(([, d]) => d > 0.5).length;
console.log(`files with >0.5 ms delta: ${compiledFiles}`);
